declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(404);exit;}
function platformPaymentAction(string $a,array $d,array $u): array{
 if($a==='admin-refund-execute'){
  platformAdmin($u);$id=accountString($d,'id',32,true);if(!platformFeatures()['payments']['configured'])accountError(503,'PAYMOB_NOT_CONFIGURED');
  $r=platformTransaction(function()use($id,$u){$row=accountQuery('SELECT r.*,p.provider_transaction_id FROM idea_refunds r JOIN idea_payments p ON p.id=r.payment_id WHERE r.id=?'.platformLock(),[$id])->fetch();if(!$row||$row['status']!=='requested'||!$row['provider_transaction_id'])accountError(409,'REFUND_NOT_EXECUTABLE');accountQuery("UPDATE idea_refunds SET status='processing',updated_at=? WHERE id=?",[platformNow(),$id]);platformAudit($u,'refund-execute',$id);return $row;});
  try{[$code,$result]=platformHttp('https://accept.paymob.com/api/acceptance/void_refund/refund',['Authorization: Token '.platformSecret('PAYMOB_SECRET_KEY'),'Content-Type: application/json'],['transaction_id'=>(int)$r['provider_transaction_id'],'amount_cents'=>(int)$r['amount_cents']]);if($code<200||$code>=300)accountError(502,'REFUND_PROVIDER_REJECTED');accountQuery('UPDATE idea_refunds SET provider_reference=?,updated_at=? WHERE id=?',[(string)($result['id']??''),platformNow(),$id]);return ['status'=>'processing','settlement_confirmation_required'=>true];}catch(Throwable $e){accountQuery("UPDATE idea_refunds SET status='unknown',updated_at=? WHERE id=?",[platformNow(),$id]);throw $e;}
 }
 $o=platformOrder($u,accountString($d,'order_id',32,true));
 if($a==='refund-request'){if($o['user_id']!==$u['id']&&$u['role']!=='admin')accountError(403,'FORBIDDEN');$reason=accountString($d,'reason',1000,true);return platformTransaction(function()use($o,$reason,$u){$p=accountQuery("SELECT * FROM idea_payments WHERE order_id=? AND status='paid'".platformLock(),[$o['id']])->fetch();if(!$p)accountError(409,'NO_CAPTURED_PAYMENT');if(accountQuery("SELECT id FROM idea_refunds WHERE order_id=? AND status IN ('requested','processing','completed')",[$o['id']])->fetch())accountError(409,'REFUND_ALREADY_REQUESTED');$id=platformId();accountQuery('INSERT INTO idea_refunds(id,order_id,payment_id,amount_cents,reason,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$o['id'],$p['id'],$p['amount_cents'],$reason,'requested',platformNow(),platformNow()]);platformAudit($u,'refund-request',$id);return ['id'=>$id,'status'=>'requested'];});}
 if($a!=='payment-start')accountError(404,'UNKNOWN_ACTION');if($o['user_id']!==$u['id'])accountError(403,'FORBIDDEN');if(!platformFeatures()['payments']['configured'])accountError(503,'PAYMOB_NOT_CONFIGURED');if($o['status']!=='awaiting_payment'||$o['reservation_expires_at']<platformNow())accountError(409,'ORDER_NOT_PAYABLE');
 // Serialize initiation per order. A timeout leaves an explicit unknown outcome;
 // it must be reconciled instead of blindly creating another provider payment.
 $p=platformTransaction(function()use($o){accountQuery('SELECT id FROM idea_orders WHERE id=?'.platformLock(),[$o['id']]);$old=accountQuery('SELECT * FROM idea_payments WHERE order_id=? ORDER BY created_at DESC LIMIT 1',[$o['id']])->fetch();if($old)return $old;$id=platformId();accountQuery('INSERT INTO idea_payments(id,order_id,provider,status,amount_cents,currency,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$o['id'],'paymob','initiating',$o['total_cents'],'EGP',platformNow(),platformNow()]);return ['id'=>$id,'new'=>true];});
 if(empty($p['new'])){if($p['checkout_url']&&$p['status']==='pending')return ['checkout_url'=>$p['checkout_url']];accountError(409,'PAYMENT_RECONCILIATION_REQUIRED');}
 $cfg=platformConfig();$secret=platformSecret('PAYMOB_SECRET_KEY');$live=($cfg['payment_mode']??'sandbox')==='live';if(($live&&!str_starts_with($secret,'sk_live_'))||(!$live&&!str_starts_with($secret,'sk_test_')))accountError(503,'PAYMOB_MODE_MISMATCH');
 $address=$o['address_snapshot'];$names=preg_split('/\s+/',$address['recipient'],2);$base=rtrim(accountConfig()['site_url'],'/');$api=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME'])),'/').'/platform.php';
 try{[$code,$result]=platformHttp('https://accept.paymob.com/v1/intention/',['Authorization: Token '.$secret,'Content-Type: application/json'],['amount'=>(int)$o['total_cents'],'currency'=>'EGP','payment_methods'=>array_map('intval',$cfg['paymob_integration_ids']),'items'=>[['name'=>'IDEA order '.$o['id'],'amount'=>(int)$o['total_cents'],'quantity'=>1]],'billing_data'=>['first_name'=>$names[0],'last_name'=>$names[1]??$names[0],'email'=>$u['email'],'phone_number'=>$address['phone'],'apartment'=>$address['apartment'],'floor'=>$address['floor_number'],'street'=>$address['street'],'building'=>$address['building'],'city'=>$address['city'],'state'=>$address['governorate'],'country'=>'EG','postal_code'=>$address['postal_code']],'special_reference'=>$p['id'],'notification_url'=>$base.$api.'?action=payment-webhook','redirection_url'=>$base.'/account/orders/'.$o['id'],'expiration'=>max(60,intdiv((int)$o['reservation_expires_at']-platformNow(),1000))]);if($code<200||$code>=300||empty($result['client_secret'])||empty($result['intention_order_id']))accountError(502,'PAYMOB_INITIATION_FAILED');$url='https://accept.paymob.com/unifiedcheckout/?'.http_build_query(['publicKey'=>platformSecret('PAYMOB_PUBLIC_KEY'),'clientSecret'=>$result['client_secret']]);accountQuery("UPDATE idea_payments SET status='pending',provider_order_id=?,provider_intention_id=?,checkout_url=?,updated_at=? WHERE id=?",[(string)$result['intention_order_id'],(string)($result['id']??''),$url,platformNow(),$p['id']]);return ['checkout_url'=>$url];}catch(Throwable $e){accountQuery("UPDATE idea_payments SET status='unknown',updated_at=? WHERE id=?",[platformNow(),$p['id']]);throw $e;}
}
function platformPaymentHmac(array $o): string{$keys=['amount_cents','created_at','currency','error_occured','has_parent_transaction','id','integration_id','is_3d_secure','is_auth','is_capture','is_refunded','is_standalone_payment','is_voided','order.id','owner','pending','source_data.pan','source_data.sub_type','source_data.type','success'];$text='';foreach($keys as $key){$v=$o;foreach(explode('.',$key) as $part){if(!is_array($v)||!array_key_exists($part,$v))accountError(400,'PAYMENT_CALLBACK_INVALID');$v=$v[$part];}$text.=is_bool($v)?($v?'true':'false'):(string)$v;}return hash_hmac('sha512',$text,platformSecret('PAYMOB_HMAC_SECRET'));}
function platformPaymentWebhook(string $raw): array{
 if(!platformSecret('PAYMOB_HMAC_SECRET'))accountError(503,'PAYMOB_NOT_CONFIGURED');$body=json_decode($raw,true);$o=$body['obj']??null;if(!is_array($o))accountError(400,'PAYMENT_CALLBACK_INVALID');$hmac=$_GET['hmac']??'';if(!is_string($hmac)||!preg_match('/^[a-f0-9]{128}$/iD',$hmac)||!hash_equals(platformPaymentHmac($o),strtolower($hmac)))accountError(403,'PAYMENT_SIGNATURE_INVALID');
 return platformTransaction(function()use($o,$raw){$p=accountQuery('SELECT * FROM idea_payments WHERE provider_order_id=?'.platformLock(),[(string)$o['order']['id']])->fetch();if(!$p)accountError(404,'PAYMENT_NOT_FOUND');$order=accountQuery('SELECT * FROM idea_orders WHERE id=?'.platformLock(),[$p['order_id']])->fetch();if((int)$o['amount_cents']!==(int)$p['amount_cents']||$o['currency']!==$p['currency']||!in_array((int)$o['integration_id'],array_map('intval',platformConfig()['paymob_integration_ids']??[]),true))accountError(409,'PAYMENT_DETAILS_MISMATCH');
 $event=hash('sha256',$raw);if(accountQuery('SELECT event_key FROM idea_payment_events WHERE event_key=?',[$event])->fetch())return ['received'=>true,'duplicate'=>true];accountQuery('INSERT INTO idea_payment_events(event_key,payment_id,kind,payload_hash,created_at) VALUES(?,?,?,?,?)',[$event,$p['id'],'transaction',hash('sha256',$raw),platformNow()]);
 if(!empty($o['pending']))return ['received'=>true];if(!empty($o['is_refunded'])){$refund=accountQuery("SELECT * FROM idea_refunds WHERE payment_id=? AND status='processing'".platformLock(),[$p['id']])->fetch();if($refund&&(int)$refund['amount_cents']===(int)$p['amount_cents']&&(string)$o['id']===$p['provider_transaction_id']){accountQuery("UPDATE idea_refunds SET status='completed',updated_at=? WHERE id=?",[platformNow(),$refund['id']]);accountQuery("UPDATE idea_payments SET status='refunded',updated_at=? WHERE id=?",[platformNow(),$p['id']]);accountQuery("UPDATE idea_orders SET payment_status='refunded',updated_at=? WHERE id=?",[platformNow(),$order['id']]);accountQuery("UPDATE idea_invoices SET status='refunded' WHERE order_id=?",[$order['id']]);}else accountQuery("UPDATE idea_payments SET status='refund_review',updated_at=? WHERE id=?",[platformNow(),$p['id']]);return ['received'=>true];}
 if(empty($o['success'])||!empty($o['error_occured'])||!empty($o['is_voided'])){if($p['status']!=='paid')accountQuery("UPDATE idea_payments SET status='failed',updated_at=? WHERE id=?",[platformNow(),$p['id']]);return ['received'=>true];}
 if(!empty($o['is_auth'])||empty($o['is_capture'])&&empty($o['is_standalone_payment']))return ['received'=>true];if($p['status']==='paid')return ['received'=>true,'duplicate'=>true];
 $ready=$order['status']==='awaiting_payment'&&$order['reservation_expires_at']>=platformNow();$items=accountQuery('SELECT * FROM idea_order_items WHERE order_id=? ORDER BY variant_id',[$order['id']])->fetchAll();foreach($items as $i){$v=accountQuery('SELECT * FROM idea_commerce_variants WHERE id=?'.platformLock(),[$i['variant_id']])->fetch();if((int)$v['stock_milli']<(int)$i['quantity_milli']||(int)$v['reserved_milli']<(int)$i['quantity_milli'])$ready=false;}
 accountQuery('UPDATE idea_payments SET status=?,provider_transaction_id=?,updated_at=? WHERE id=?',[$ready?'paid':'payment_review',(string)$o['id'],platformNow(),$p['id']]);if(!$ready){accountQuery("UPDATE idea_orders SET payment_status='payment_review',updated_at=? WHERE id=?",[platformNow(),$order['id']]);return ['received'=>true,'review_required'=>true];}
 foreach($items as $i)accountQuery('UPDATE idea_commerce_variants SET stock_milli=stock_milli-?,reserved_milli=reserved_milli-? WHERE id=?',[$i['quantity_milli'],$i['quantity_milli'],$i['variant_id']]);accountQuery("UPDATE idea_orders SET payment_status='paid',status='confirmed',reservation_expires_at=NULL,updated_at=? WHERE id=?",[platformNow(),$order['id']]);$order['payment_status']='paid';$order['status']='confirmed';platformCreateInvoice($order);platformNotify($order['user_id'],'payment-paid:'.$p['id'],'IDEA — Payment confirmed','Your payment was confirmed by the payment provider.','/account/orders/'.$order['id']);return ['received'=>true];
 });
}
